class Cache {
  constructor(capacity, options = {}) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error("Capacity must be a positive integer");
    }

    this.capacity = capacity;
    this.map = new Map();
    this.ttl = options.ttl || Infinity;
    this.now = options.now || Date.now;
  }

  set(key, value, options = {}) {
    if (this.map.has(key)) {
      // Update existing key
      this.map.delete(key);
    } else if (this.map.size >= this.capacity) {
      // Remove least recently used item (first item in the map)
      const firstKey = this.map.keys().next().value;
      this.map.delete(firstKey);
    }

    const ttl = options.ttl !== undefined ? options.ttl : this.ttl;
    const timestamp = this.now();

    this.map.set(key, { value, timestamp, ttl });
  }

  get(key) {
    if (!this.map.has(key)) {
      return undefined;
    }

    const entry = this.map.get(key);
    const { value, timestamp, ttl } = entry;

    // Check if entry has expired
    if (this.now() - timestamp > ttl) {
      this.map.delete(key);
      return undefined;
    }

    // Move to end to mark as recently used
    this.map.delete(key);
    this.map.set(key, entry);

    return value;
  }

  peek(key) {
    if (!this.map.has(key)) {
      return undefined;
    }

    const entry = this.map.get(key);
    const { value, timestamp, ttl } = entry;

    // Check if entry has expired
    if (this.now() - timestamp > ttl) {
      this.map.delete(key);
      return undefined;
    }

    // Return the value without marking as recently used
    return value;
  }

  has(key) {
    if (!this.map.has(key)) {
      return false;
    }

    const entry = this.map.get(key);
    const { timestamp, ttl } = entry;

    // Check if entry has expired
    if (this.now() - timestamp > ttl) {
      this.map.delete(key);
      return false;
    }

    return true;
  }

  size() {
    let count = 0;
    const now = this.now();

    for (const [key, entry] of this.map.entries()) {
      const { timestamp, ttl } = entry;

      // Check if entry has expired
      if (now - timestamp <= ttl) {
        count++;
      } else {
        // Remove expired entry
        this.map.delete(key);
      }
    }

    return count;
  }

  delete(key) {
    return this.map.delete(key);
  }

  clear() {
    this.map.clear();
  }

  keys() {
    return Array.from(this.map.keys()).reverse();
  }
}

// Export the Cache class
module.exports = { Cache };

// Test cache expiry functionality
const { Cache } = require('./s7_cache.js');

console.log("Testing Cache expiry functionality...");

// Test 1: Basic expiry functionality
console.log("\n=== Test 1: Basic expiry ===");
const cache = new Cache(3, { ttl: 100 }); // 100ms TTL

cache.set("a", 1);
cache.set("b", 2);
cache.set("c", 3);

console.log("Initial size:", cache.size()); // Should be 3
console.log("Has 'a':", cache.has("a")); // Should be true
console.log("Get 'a':", cache.get("a")); // Should be 1

// Wait for expiry
setTimeout(() => {
  console.log("After expiry wait:");
  console.log("Size:", cache.size()); // Should be 0
  console.log("Has 'a':", cache.has("a")); // Should be false
  console.log("Get 'a':", cache.get("a")); // Should be undefined

  // Test 2: Per-entry TTL override
  console.log("\n=== Test 2: Per-entry TTL override ===");
  const cache2 = new Cache(2, { ttl: 1000 }); // Default 1000ms

  cache2.set("x", 10, { ttl: 50 }); // 50ms TTL
  cache2.set("y", 20, { ttl: 200 }); // 200ms TTL
  cache2.set("z", 30); // Default 1000ms TTL

  console.log("Initial size:", cache2.size()); // Should be 3
  console.log("Get 'x':", cache2.get("x")); // Should be 10
  console.log("Get 'y':", cache2.get("y")); // Should be 20
  console.log("Get 'z':", cache2.get("z")); // Should be 30

  // Wait for 'x' to expire
  setTimeout(() => {
    console.log("After 'x' expiry:");
    console.log("Size:", cache2.size()); // Should be 2
    console.log("Get 'x':", cache2.get("x")); // Should be undefined
    console.log("Get 'y':", cache2.get("y")); // Should be 20
    console.log("Get 'z':", cache2.get("z")); // Should be 30

    // Wait for 'y' to expire
    setTimeout(() => {
      console.log("After 'y' expiry:");
      console.log("Size:", cache2.size()); // Should be 1
      console.log("Get 'y':", cache2.get("y")); // Should be undefined
      console.log("Get 'z':", cache2.get("z")); // Should be 30

      // Test 3: Peek with expiry
      console.log("\n=== Test 3: Peek with expiry ===");
      const cache3 = new Cache(2, { ttl: 50 });

      cache3.set("p", 100);
      console.log("Peek 'p':", cache3.peek("p")); // Should be 100

      setTimeout(() => {
        console.log("After 'p' expiry:");
        console.log("Peek 'p':", cache3.peek("p")); // Should be undefined
        console.log("Size:", cache3.size()); // Should be 0

        console.log("\nAll expiry tests completed!");
      }, 60);
    }, 160);
  }, 60);
}, 110);

