write_file|{"path":"s7_cache_fixed.js","content":"class Cache {
  constructor(capacity, options = {}) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error("Capacity must be a positive integer");
    }

    this.capacity = capacity;
    this.map = new Map();
    this.ttl = options.ttl || Infinity;
    this.now = options.now || Date.now;
  }

  set(key, value, options = {}) {
    if (this.map.has(key)) {
      // Update existing key
      this.map.delete(key);
    } else if (this.map.size >= this.capacity) {
      // Remove least recently used item (first item in the map)
      const firstKey = this.map.keys().next().value;
      this.map.delete(firstKey);
    }

    const ttl = options.ttl !== undefined ? options.ttl : this.ttl;
    const timestamp = this.now();

    this.map.set(key, { value, timestamp, ttl });
  }

  get(key) {
    if (!this.map.has(key)) {
      return undefined;
    }

    const entry = this.map.get(key);
    const { value, timestamp, ttl } = entry;

    // Check if entry has expired
    if (this.now() - timestamp > ttl) {
      this.map.delete(key);
      return undefined;
    }

    // Move to end to mark as recently used
    this.map.delete(key);
    this.map.set(key, entry);

    return value;
  }

  peek(key) {
    if (!this.map.has(key)) {
      return undefined;
    }

    const entry = this.map.get(key);
    const { value, timestamp, ttl } = entry;

    // Check if entry has expired
    if (this.now() - timestamp > ttl) {
      this.map.delete(key);
      return undefined;
    }

    // Return the value without marking as recently used
    return value;
  }

  has(key) {
    if (!this.map.has(key)) {
      return false;
    }

    const entry = this.map.get(key);
    const { timestamp, ttl } = entry;

    // Check if entry has expired
    if (this.now() - timestamp > ttl) {
      this.map.delete(key);
      return false;
    }

    return true;
  }

  size() {
    let count = 0;
    const now = this.now();

    for (const [key, entry] of this.map.entries()) {
      const { timestamp, ttl } = entry;

      // Check if entry has expired
      if (now - timestamp <= ttl) {
        count++;
      } else {
        // Remove expired entry
        this.map.delete(key);
      }
    }

    return count;
  }

  delete(key) {
    return this.map.delete(key);
  }

  clear() {
    this.map.clear();
  }

  keys() {
    return Array.from(this.map.keys()).reverse();
  }
}

// Export the Cache class
module.exports = { Cache };"}|OK: wrote 2540 bytes to s7_cache_fixed.js

